def run(s, name, image, port, environment=None, replicas=1, resources=None, case="neither", fault="none", healthcheck=None):
    v = version(image)
    if healthcheck is None:
        default = CONTRACT["healthcheck"]
        healthcheck = {"test": default["command"], "interval": str(default["interval_seconds"]) + "s",
            "timeout": str(default["timeout_seconds"]) + "s", "retries": default["retries"]}
    healthcheck = resolved_healthcheck(healthcheck)
    if name in s["containers"] and alive(s["containers"][name]): raise ValueError("identity already running")
    if not 1 <= replicas <= RUNTIME["replica_bounds"]["max"]: raise ValueError("replica bounds")
    env = dict(environment or {})
    secret_key = RUNTIME["secret_environment_variable"]
    if secret_key in env: raise ValueError("Use runtime secret injection, not persisted environment")
    if secret_key not in os.environ: raise PermissionError("runtime secret variable required")
    cmd = [sys.executable, "endpoint_scaffold.py", "--port", str(port), "--version", v, "--case", case, "--fault", fault]
    out = open(".offline_server_output.log", "ab")
    child = subprocess.Popen(cmd, env={**os.environ, **{k:str(x) for k,x in env.items()}}, stdout=out, stderr=out, start_new_session=True)
    time.sleep(0.2)
    running = child.poll() is None
    s["containers"][name] = {"Name": name, "pid": child.pid, "Config": {"Image": image, "Env": env, "SecretReferences": [RUNTIME["secret_reference"]]}, "State": {"Running": running, "Status": "running" if running else "exited", "ExitCode": 0 if running else child.returncode, "Health": {"Status": "starting"}}, "HostPort": port, "ContainerPort": RUNTIME["CONTAINER_PORT"], "endpoint": "http://"+CONTRACT["host"]+":"+str(port), "replicas": replicas, "resources": resources or {}, "case": case, "fault": fault}
    c = s["containers"][name]
    c["Config"]["Healthcheck"] = healthcheck
    if running and not healthcheck.get("disable") and healthcheck.get("test") != ["NONE"]:
        result_path = str(ROOT / (".offline_health_" + str(child.pid) + ".json"))
        Path(result_path).unlink(missing_ok=True)
        monitor = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), "--health-worker",
            str(child.pid), json.dumps({"healthcheck": healthcheck, "environment": env}), result_path],
            stdout=out, stderr=out, start_new_session=True)
        c["health_pid"], c["health_result"] = monitor.pid, result_path
        c["State"]["Health"] = {"Status": "starting", "FailingStreak": 0, "Log": []}
    elif healthcheck.get("disable") or healthcheck.get("test") == ["NONE"]:
