def stop(s, name, remove=False):
    c=s["containers"][name]
    if c.get("health_pid"):
        try: os.killpg(c["health_pid"], signal.SIGTERM)
        except ProcessLookupError: pass
    if alive(c):
        os.killpg(c["pid"], signal.SIGTERM); c["State"].update(Running=False, Status="exited")
    record(s, "stop", name=name)
    if remove: del s["containers"][name]; record(s, "remove", name=name)
def option(args, names, default=None):
    for i,a in enumerate(args):
        if a in names: return args[i+1]
        for n in names:
            if a.startswith(n+"="): return a.split("=",1)[1]
    return default
def config(path):
    # PyYAML is the declared dependency; secrets remain reference names.
    try: import yaml
    except ImportError: import offline_yaml as yaml
    text=Path(path).read_text()
    text=re.sub(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}", lambda m: os.environ[m[1]], text)
    value=yaml.safe_load(text)
    for svc in value["services"].values():
        version(svc["image"])
        if RUNTIME["secret_environment_variable"] in svc.get("environment", {}): raise ValueError("secret must be reference-only")
