# Runtime-secret-only authentication fixture. No credential literals supplied.
import json, os
from pathlib import Path
from supplied_prediction import contract
class GoogleAuthError(Exception): pass
cases = {r["case_id"]: r for r in json.loads(Path("authentication_cases.json").read_text())}
active_case = "authorized"
def select_case(case_id):
    global active_case
    if case_id not in cases: raise KeyError(case_id)
    active_case = case_id
def runtime_secret(case_id="authorized"):
    if case_id == "missing": return None
    key = contract["injected_secret_variable"]
    if case_id != "authorized": key += "_" + case_id.upper()
    return os.environ[key]
def verify_oauth2_token(token, request=None, audience=None):
    if audience != contract["expected_audience"]: raise ValueError("audience")
    case_id = active_case
    # Named runtime-injected secrets allow all cases against one running server.
    for candidate in cases:
        if candidate != "missing":
            try:
                if token == runtime_secret(candidate): case_id = candidate; break
            except KeyError: pass
    if not token: raise ValueError("missing")
    try: expected = runtime_secret(case_id)
    except KeyError: raise ValueError("unknown token") from None
    if token != expected: raise ValueError("invalid token")
    case = cases[case_id]
    if case.get("verifier_exception") == "ValueError": raise ValueError("invalid token")
    if case.get("verifier_exception") == "GoogleAuthError": raise GoogleAuthError("invalid issuer")
    return dict(case["verified_claims"])
def permitted_subjects(): return list(contract["permitted_subjects"])

