"""Infrastructure-only safe YAML subset decoder, not learner PyYAML round-trip code.
Used only if the declared PyYAML dependency is absent in this offline harness.
Accepts JSON (a YAML subset), indented mappings/lists and ordinary scalar values.
No constructors, object tags, aliases or executable deserialization are supported.
"""
import ast, json, re
def scalar(text):
    text=text.strip()
    if not text: return None
    if text.startswith(("!", "&", "*")): raise ValueError("unsupported YAML tag/alias")
    if text[0:1] in ["'", '"']:
        return ast.literal_eval(text)
    if text.lower() in ["true", "false"]: return text.lower()=="true"
    if text.lower() in ["null", "~"]: return None
    if re.fullmatch(r"[-+]?\d+",text): return int(text)
    if re.fullmatch(r"[-+]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][-+]?\d+)?",text): return float(text)
    if text.startswith("["):
        try: return json.loads(text)
        except json.JSONDecodeError:
            if not text.endswith("]"): raise ValueError("flow list")
            return [scalar(v) for v in text[1:-1].split(",")] if text[1:-1].strip() else []
    if text.startswith("{"):
        try: return json.loads(text)
        except json.JSONDecodeError: raise ValueError("Install declared PyYAML for non-JSON flow mappings")
    return text
def safe_load(text):
    try: return json.loads(text)
    except json.JSONDecodeError: pass
    lines=[]
    for raw in text.splitlines():
        if "\t" in raw: raise ValueError("YAML indentation must use spaces")
        if not raw.strip() or raw.lstrip().startswith("#") or raw.strip()=="---": continue
        lines.append((len(raw)-len(raw.lstrip()),raw.strip()))
    def mapping_item(body):
        m=re.match(r"(.+?):(?:\s+|$)(.*)",body)
        if not m: raise ValueError("mapping syntax")
        return str(scalar(m[1])),m[2]
    def block(index, indent):
        is_list=lines[index][1]=="-" or lines[index][1].startswith("- ")
        result=[] if is_list else {}
        while index<len(lines):
            level,body=lines[index]
            if level<indent: break
            if level!=indent: raise ValueError("unexpected indentation")
            if is_list:
                if body!="-" and not body.startswith("- "): break
                value=body[1:].strip();index+=1
                if not value:
                    if index>=len(lines) or lines[index][0]<=indent: result.append(None)
                    else:
                        child,index=block(index,lines[index][0]);result.append(child)
                else: result.append(scalar(value))
            else:
                if body=="-" or body.startswith("- "): break
                key,value=mapping_item(body);index+=1
                if value: result[key]=scalar(value)
                elif index<len(lines) and (lines[index][0]>indent or (lines[index][0]==indent and lines[index][1].startswith("-"))):
                    child,index=block(index,lines[index][0]);result[key]=child
                else: result[key]=None
        return result,index
    if not lines: return None
    value,index=block(0,lines[0][0])
    if index!=len(lines): raise ValueError("unconsumed YAML input")
    return value

