import argparse, json, os, time
from pathlib import Path
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from supplied_prediction import predict, reject_malformed, contract
prediction_calls = []
sanitized_logs = []
def capture(kind, value):
    if kind == "prediction_calls": prediction_calls.append(value)
    else: sanitized_logs.append(value)
    with open(kind + ".jsonl", "a") as stream: stream.write(json.dumps(value) + "\n")
class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args): pass  # Never log URL, token, or protected body.
    def reply(self, status, payload):
        body = payload if isinstance(payload, bytes) else json.dumps(payload).encode("utf-8")
        self.send_response(status); self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body))); self.end_headers()
        try: self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError): pass
    def do_GET(self):
        if self.path != contract["readiness_route"]: return self.reply(404, {})
        if Path("initialization_cases.json").exists():
            from server_scaffold import dispatch_get
            return dispatch_get(self)
        return self.reply(contract["success_status"], contract["ready_payload"])
    def do_POST(self):
        if self.path != contract["prediction_route"]: return self.reply(404, {})
        # Timeout control deliberately precedes dispatch: no handler telemetry.
        if self.server.fault == "timeout":
            time.sleep(contract["timeout_seconds"] + 1)
            self.close_connection = True
            return  # no prediction-handler dispatch/record for this external timeout
        try:
            body = self.rfile.read(int(self.headers.get("Content-Length", "0")))
            if Path("authentication_cases.json").exists():
                import learner
                import auth_fixture
                # learner owns extraction, verification, allow-list enforcement,
                # ValueError/GoogleAuthError conversion to PermissionError.
                learner.authorize_prediction(self.headers, auth_fixture)
            if Path("prediction_handler.py").exists():
                from prediction_handler import handle_prediction
                status, result = handle_prediction(body, self.server.fault)
            else:
                payload = json.loads(body)
                values = reject_malformed(payload)
                capture("prediction_calls", {"call_index": len(prediction_calls), "version": self.server.version})
                result = predict(values, self.server.version)
                status = contract["success_status"]
            if self.server.version == "B":
                # Fixture-injected B fault: HTTP 500; package implementation unchanged.
                return self.reply(500, {"error": "fixture_release_fault", "version": "B"})
            self.reply(status, result)
        except PermissionError:
            capture("sanitized_logs", {"error_class": "PermissionError"})
            self.reply(contract["denied_status"], {"error": "PermissionError"})
        except (ValueError, TypeError, KeyError, UnicodeError):
            capture("sanitized_logs", {"error_class": "ValueError"})
            self.reply(contract["schema_rejection_status"], {"error": "ValueError"})
        except Exception as error:
            capture("sanitized_logs", {"error_class": type(error).__name__})
            self.reply(500, {"error": type(error).__name__})
def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=contract["port"])
    parser.add_argument("--version", default=contract["version"], choices=["A", "B"])
    parser.add_argument("--fault", default="none", choices=["none", "handled_error", "connection_refusal", "timeout"])
    parser.add_argument("--case", default="neither")
