    # not an unconditional readiness probe.
    if stored.get("health_result") and Path(stored["health_result"]).exists():
        stored["State"]["Health"] = json.loads(Path(stored["health_result"]).read_text())
    if not stored["State"]["Running"]: stored["State"]["Status"] = "exited"
