    s["containers"][name] = {"Name": name, "pid": child.pid, "Config": {"Image": image, "Env": env, "SecretReferences": [RUNTIME["secret_reference"]]}, "State": {"Running": running, "Status": "running" if running else "exited", "ExitCode": 0 if running else child.returncode, "Health": {"Status": "starting"}}, "HostPort": port, "ContainerPort": RUNTIME["CONTAINER_PORT"], "endpoint": "http://"+CONTRACT["host"]+":"+str(port), "replicas": replicas, "resources": resources or {}, "case": case, "fault": fault}
