"""
import argparse, copy, csv, json, os, re, signal, subprocess, sys, time
from pathlib import Path
ROOT = Path(__file__).resolve().parent
os.chdir(ROOT)
CONTRACT = json.loads(Path("contract.json").read_text())
RUNTIME = json.loads(Path("runtime_contract.json").read_text())
RELEASES = list(csv.DictReader(Path("release_records.csv").open())) if Path("release_records.csv").exists() else []
STATE = Path(".offline_runtime_state.json")
def load():
    return json.loads(STATE.read_text()) if STATE.exists() else {"offline": True, "containers": {}, "events": [], "instance": RUNTIME["original_instance_status"], "branch": RUNTIME["BASE_BRANCH"], "commits": []}
def save(s): STATE.write_text(json.dumps(s, indent=2))
def record(s, event, **fields):
    s["events"].append({"sequence": len(s["events"]), "event": event, **fields}); save(s)
def version(image):
    for r in RELEASES:
        if r["image_reference"] == image: return r["version"]
    raise ValueError("Only supplied fixture immutable artifact identities are allowed")
def alive(c):
    if not c.get("pid"): return False
    try: os.kill(c["pid"], 0); return c["State"]["Running"]
    except ProcessLookupError: return False
def health_seconds(value):
    if isinstance(value, (int, float)): return float(value)
    text = str(value)
    units = {"ns": 1e-9, "us": 1e-6, "ms": 1e-3, "s": 1, "m": 60, "h": 3600}
    parts = re.findall(r"([0-9]+(?:\.[0-9]+)?)(ns|us|ms|s|m|h)", text)
    if not parts or "".join(n + u for n, u in parts) != text: raise ValueError("healthcheck duration")
    return sum(float(n) * units[u] for n, u in parts)
def resolved_healthcheck(fields):
    hc = copy.deepcopy(fields)
    if hc.get("disable") or hc.get("test") == ["NONE"]: return hc
    test = hc["test"]
    if isinstance(test, str): test = ["CMD-SHELL", test]
    if not isinstance(test, list) or len(test) < 2 or test[0] not in ["CMD", "CMD-SHELL"]: raise ValueError("healthcheck command")
    hc["test"] = test
    # Unspecified timing fields use the supplied fixture contract, not typed values.
    for key in ["interval", "timeout"]:
        hc.setdefault(key, str(CONTRACT["healthcheck"][key + "_seconds"]) + "s")
        if health_seconds(hc[key]) <= 0: raise ValueError("healthcheck duration")
    hc.setdefault("retries", CONTRACT["healthcheck"]["retries"])
    if type(hc["retries"]) is not int or hc["retries"] <= 0: raise ValueError("healthcheck retries")
    return hc
def health_worker(pid, configuration, result_path):
    hc = configuration["healthcheck"]
    interval, timeout = health_seconds(hc["interval"]), health_seconds(hc["timeout"])
    health = {"Status": "starting", "FailingStreak": 0, "Log": []}
    target = Path(result_path)
    next_check = time.monotonic() + interval
    while True:
        try: os.kill(pid, 0)
        except ProcessLookupError: return
        time.sleep(max(0, next_check - time.monotonic()))
        start = time.time()
        test = hc["test"]
        command = test[1:] if test[0] == "CMD" else ["/bin/sh", "-c", " ".join(test[1:])]
        env = {**os.environ, **{k: str(v) for k, v in configuration["environment"].items()}}
        try:
            outcome = subprocess.run(command, cwd=ROOT, env=env, stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=timeout)
            code, output = outcome.returncode, outcome.stdout.decode("utf-8", errors="replace")
        except subprocess.TimeoutExpired:
            code, output = -1, "configured healthcheck timed out"
        except OSError as error:
            code, output = -1, type(error).__name__
        if code == 0:
            health["Status"], health["FailingStreak"] = "healthy", 0
        else:
            health["FailingStreak"] += 1
            if health["FailingStreak"] >= hc["retries"]: health["Status"] = "unhealthy"
        health["Log"].append({"Start": start, "End": time.time(), "ExitCode": code, "Output": output})
        health["Log"] = health["Log"][-5:]
