def process_observation(s, name, action):
    c=s["containers"][name]
    if not alive(c): raise ValueError("service not running")
    parent=c["pid"]
    pid_file=Path(".offline_workers_"+str(parent)+".json")
    children=json.loads(pid_file.read_text()) if pid_file.exists() else []
    pids=[parent]+children
    def sample():
        result=[]
        for pid in pids:
            try:
                fields=Path("/proc/"+str(pid)+"/stat").read_text().split()
                cpu=(int(fields[13])+int(fields[14]))/os.sysconf("SC_CLK_TCK")
                memory=int(fields[23])*os.sysconf("SC_PAGE_SIZE")/(1024*1024)
                result.append({"pid":pid,"process_kind":"prediction_worker" if pid in children else "supervisor", "cpu_seconds":cpu,"memory_mib":memory})
            except FileNotFoundError: pass
        return result
    if action=="top":
        result={"offline_local_execution":True,"Name":name,"configured_worker_limit":c["Config"]["Env"].get(RUNTIME["worker_limit_key"]),"processes":sample()}
    else:
        start=time.monotonic();before=sample();time.sleep(0.1);after=sample();elapsed=time.monotonic()-start
        result={"offline_local_execution":True,"Name":name,"elapsed_seconds":elapsed,"cpu_percent":100*(sum(r["cpu_seconds"] for r in after)-sum(r["cpu_seconds"] for r in before))/elapsed,"memory_mib":sum(r["memory_mib"] for r in after)}
    record(s,action,name=name,observation=result);return result

def logs(s, names):
    result={n:(["initialization completed"] if alive(s["containers"][n]) else ["service exited"]) for n in names}
    if Path("sanitized_logs.jsonl").exists(): result["captured_error_classes"]=[json.loads(x) for x in Path("sanitized_logs.jsonl").read_text().splitlines()]
    for name in names:
        c=s["containers"][name]
        if c["case"]=="initialization_failure": result[name]=["initialization failed"]
        elif c["case"] in ["neither", "model_only", "preprocessor_only"] and Path("initialization_cases.json").exists(): result[name]=["initialization incomplete"]
        if version(c["Config"]["Image"])=="B": result[name].append("fixture_release_fault: HTTP 500 injected by runtime")
