def command(s, args):
    if args[0]=="docker":
        args=args[1:]
        if args[0]=="compose": return compose(s,args[1:])
        if args[0]=="container": args=args[1:]
        if args[0]=="image" and args[1]=="inspect": return {"Id":args[-1],"offline_version":version(args[-1])}
        if args[0]=="run":
            name=option(args,["--name"],RUNTIME["NAME"]); mapping=option(args,["-p","--publish"],str(RUNTIME["HOST_PORT"])+":"+str(RUNTIME["CONTAINER_PORT"]))
            host,container=map(int,mapping.split(":"))
            if container!=RUNTIME["CONTAINER_PORT"]: raise ValueError("container port")
            env={}
            for i,x in enumerate(args):
                if x in ["--env","-e"]:
                    k,v=args[i+1].split("=",1); env[k]=v
            return run(s,name,args[-1],host,env)
        if args[0] in ["top", "stats"]: return process_observation(s, args[-1], args[0])
        if args[0]=="inspect":
            answer=inspect(s,args[-1]); record(s,"inspect",name=args[-1],observation=answer); return answer
        if args[0]=="logs": return logs(s,[args[-1]])
        if args[0] in ["stop","rm"]:
            name=args[-1]
            if args[0]=="rm":
