    if args[0]=="gcloud":
        if RUNTIME["INSTANCE"] not in args: raise ValueError("instance scope")
        if option(args,["--zone"])!=RUNTIME["ZONE"]: raise ValueError("zone scope")
        action=args[3] if args[2]=="instances" else args[2]
        if action=="start": s["instance"]="RUNNING"
        elif action=="stop": s["instance"]="TERMINATED"
        elif action=="ssh" and s["instance"]!="RUNNING": raise ValueError("instance not running")
        elif action not in ["describe","ssh"]: raise ValueError("unsupported instance action")
        record(s,"instance_"+action);return {"offline":True,"name":RUNTIME["INSTANCE"],"zone":RUNTIME["ZONE"],"status":s["instance"],"connection":"local scaffold"}
    if args[:2]==["aws","application-autoscaling"]:
        if args[2] not in ["register-scalable-target","put-scaling-policy"]: raise ValueError("unsupported scaling action")
        s["scaling_policy"]={"command":args[2],"parameters":args[3:]};record(s,"scaling_policy",policy=s["scaling_policy"]);return s["scaling_policy"]
    if args[0]=="git":
        # Explicit fixture repository controls; never touch the pack's actual git.
        if args[1]=="checkout": s["branch"]=args[-1]
        elif args[1]=="add": s["staged"]={args[2]:Path(args[2]).read_text()}
        elif args[1]=="commit": s["commits"].append({"branch":s["branch"],"files":s.get("staged",{}),"message":option(args,["-m"])})
        elif args[1]=="merge": s["merged_branch"]=args[-1]
        else: raise ValueError("unsupported repository action")
        record(s,"repository_"+args[1]);return {"offline":True,"branch":s["branch"],"commits":s["commits"]}
