    args=sys.argv[1:];s=load()
    if not args: raise SystemExit("Use init, state, events, cleanup, serve or exec COMMAND")
    if args[0]=="init":
        save(s)
        if Path("rollback_contract.json").exists() and not s["containers"]:
            r=next(r for r in RELEASES if r["version"]=="B")
            answer=run(s,r["container_name"],r["image_reference"],int(r["host_port"]))
        elif Path("original_config.json").exists() and not s["containers"]:
