            original=json.loads(Path("original_config.json").read_text())
            Path(".offline_original.yaml").write_text(json.dumps(original, indent=2))
            answer=compose(s,["-f",".offline_original.yaml","up"])
        else: answer={"offline":True,"initialized":True,"containers":s["containers"]}
    elif args[0]=="state": answer={**s,"containers":{n:inspect(s,n) for n in s["containers"]}}
