        result=[]
        for pid in pids:
            try:
                fields=Path("/proc/"+str(pid)+"/stat").read_text().split()
                cpu=(int(fields[13])+int(fields[14]))/os.sysconf("SC_CLK_TCK")
                memory=int(fields[23])*os.sysconf("SC_PAGE_SIZE")/(1024*1024)
